final class GravatarViewHelper extends AbstractViewHelper
{
    public function initializeArguments(): void
    {
        $this->registerArgument('emailAddress', 'string', 'Email', true);
    }

    public function render(): string
    {
        $hash = md5($this->arguments['emailAddress']);
        return '<img src="https://www.gravatar.com/avatar/' . $hash . '" />';
    }
}

